def greedy(amount, coins):
    used = []
    for c in sorted(coins, reverse=True):
        while amount >= c:
            amount -= c
            used.append(c)
    return used

def fewest(amount, coins):
    best = [0] + [float("inf")] * amount
    for a in range(1, amount + 1):
        best[a] = min(best[a - c] + 1 for c in coins if c <= a)
    return best[amount]

print(greedy(6, [1, 3, 4]), fewest(6, [1, 3, 4]))              # [4, 1, 1] 2
print(greedy(63, [1, 5, 10, 25]), fewest(63, [1, 5, 10, 25]))  # [25, 25, 10, 1, 1, 1] 6

import heapq

def prim(graph, start=0):
    seen, total, chosen = {start}, 0, []
    heap = [(w, start, v) for v, w in graph[start]]
    heapq.heapify(heap)
    while heap and len(seen) < len(graph):
        w, u, v = heapq.heappop(heap)
        if v in seen:
            continue
        seen.add(v); total += w; chosen.append((u, v, w))
        for nxt, nw in graph[v]:
            if nxt not in seen:
                heapq.heappush(heap, (nw, v, nxt))
    return total, chosen

