print(bfs_path(graph, "A", "F"))    # ['A', 'B', 'D', 'F']

def dfs_order(graph, start):
    seen, order = set(), []
    def visit(node):
        seen.add(node)
        order.append(node)
        for nxt in graph[node]:
            if nxt not in seen:
                visit(nxt)
    visit(start)
    return order

