INF = float("inf")

def floyd_warshall(dist):
    n = len(dist)
    d = [row[:] for row in dist]
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    return d

graph = [[0, 3, INF, 7], [8, 0, 2, INF], [5, INF, 0, 1], [2, INF, INF, 0]]
for row in floyd_warshall(graph):
    print(row)      # [0, 3, 5, 6] / [5, 0, 2, 3] / [3, 6, 0, 1] / [2, 5, 7, 0]

import heapq

def astar(grid, start, goal):
    def h(p):                                   # Manhattan distance, never overestimates
        return abs(p[0] - goal[0]) + abs(p[1] - goal[1])
    heap, best = [(h(start), 0, start)], {start: 0}
    while heap:
        _, g, pos = heapq.heappop(heap)
        if pos == goal:
            return g
        if g > best[pos]:
            continue
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = pos[0] + dr, pos[1] + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 0:
                if g + 1 < best.get((nr, nc), float("inf")):
                    best[(nr, nc)] = g + 1
                    heapq.heappush(heap, (g + 1 + h((nr, nc)), g + 1, (nr, nc)))
    return None

grid = [[0, 0, 0, 0],
        [1, 1, 0, 1],
        [0, 0, 0, 0],
        [0, 1, 1, 0]]            # 1 = wall
print(astar(grid, (0, 0), (3, 3)))   # 6

from collections import deque

def topological_order(deps):
    indegree = {t: 0 for t in deps}
    for t, prereqs in deps.items():
        for p in prereqs:
            indegree.setdefault(p, 0)
            indegree[t] += 1
    ready = deque(t for t, d in indegree.items() if d == 0)
    order = []
    while ready:
        t = ready.popleft()
        order.append(t)
        for other, prereqs in deps.items():
            if t in prereqs:
                indegree[other] -= 1
                if indegree[other] == 0:
                    ready.append(other)
    return order if len(order) == len(indegree) else None    # None means a cycle

build = {"app": ["lib", "utils"], "lib": ["core"], "utils": ["core"], "core": []}
print(topological_order(build))                              # ['core', 'lib', 'utils', 'app']
print(topological_order({"a": ["b"], "b": ["a"]}))          # None

def pagerank(links, damping=0.85, rounds=50):
    pages = list(links)
    rank = {p: 1 / len(pages) for p in pages}
    for _ in range(rounds):
        new = {p: (1 - damping) / len(pages) for p in pages}
        for p, outs in links.items():
            share = damping * rank[p] / (len(outs) or len(pages))
            for q in (outs or pages):
                new[q] += share
        rank = new
    return rank

