for page, score in sorted(pagerank(web).items(), key=lambda kv: -kv[1]):
    print(f"{page:5s} {score:.3f}")      # home ranks highest; nobody links to old

def components(graph):
    seen, groups = set(), []
    for start in graph:
        if start in seen:
            continue
        group, stack = [], [start]
        seen.add(start)
        while stack:
            node = stack.pop()
            group.append(node)
            for nxt in graph[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        groups.append(sorted(group))
    return groups

g = {1: [2], 2: [1, 3], 3: [2], 4: [5], 5: [4], 6: []}
print(components(g))    # [[1, 2, 3], [4, 5], [6]]
